export function createShkEnvironment(services){
 const layout=Object.fromEntries(schema.layoutKeys.map((name,i)=>{const raw=BigInt(services.layout(i)),v=Number(raw);if(!Number.isSafeInteger(v)||BigInt(v)!==raw)throw Error('SHK layout exceeds exact scalar range: '+name);return[name,v];}));
 for(const[k,v]of Object.entries({pointerSize:8,longSize:8,intSize:4,charSigned:1,littleEndian:1}))if(layout[k]!==v)throw Error('Review SHK ABI '+k);
 // Pointer VALUES include the original bill_p=-1000 sentinel; only actual
 // dereferences require an exact in-memory Number address. No unsafe Number
 // input may already have rounded its pointer bits before reaching this seam.
 const ptr=v=>{if(typeof v==='number'&&!Number.isSafeInteger(v))throw Error('SHK inexact Number pointer');const bits=BigInt.asUintN(64,BigInt(v));return bits<=9007199254740991n?Number(bits):bits;};
 const address=v=>{const p=ptr(v);if(typeof p!=='number')throw Error('SHK unsafe pointer dereference');return p;};
 const {env,types,memory,type,decode,kinds}=CAdapter.createScalarAdapter(services,layout,schema,ptr,{profile:"address-cells",errors:["Review SHK scalar ","Review SHK cell ","Review SHK field "],address});
 env.global=name=>{const index=schema.globals.findIndex(g=>g.name===name);if(index<0)throw Error('Review SHK global '+name);return env.cell(services.global(index),schema.globals[index].canonical);};
 env.staticAddress=name=>{const i=schema.statics.findIndex(s=>s.name===name);if(i<0)throw Error('Review SHK static '+name);return address(services.storage(i));};
 let automatic=null;env.enterAutomatic=slots=>{const old=automatic;automatic=new Map();for(const[key,size]of slots){if(automatic.has(key))throw Error('SHK duplicate declaration key '+key);automatic.set(key,address(services.stackAlloc(size)));}return old;};env.leaveAutomatic=old=>{automatic=old;};env.automatic=(key,size)=>{if(!automatic?.has(key))throw Error('Review SHK automatic declaration '+key);return automatic.get(key);};
 env.local=(key,t,value)=>{const d=type(t),bytes=d==='p'?8:d?+d.slice(1)/8:0;if(!bytes)throw Error('Review SHK local '+t);const cell=env.cell(env.automatic(key,bytes),t);if(value!==undefined)cell.value=value;return cell;};
 env.copy=(to,from,size)=>{to=address(to);from=address(from);services.heap().copyWithin(to,from,from+size);return to;};
 env.zero=(at,size)=>{at=address(at);services.heap().fill(0,at,at+size);};
 env.variadic=(site,...args)=>{if(!schema.variadics[site])throw Error('Review SHK vararg site');return services['var'+site](...args);};
 env.callback=(site,...args)=>{if(!schema.callbacks[site])throw Error('Review SHK callback site');return services['cb'+site](...args);};
 env.functionAddress=name=>{const i=schema.functionAddresses.indexOf(name);if(i<0)throw Error('Review SHK callback identity '+name);return ptr(services.functionAddress(i));};
 const array=t=>t.match(/^(.*?)\[(\d+)\](.*)$/),size=t=>{const a=array(t);if(a)return +a[2]*size(a[1]+a[3]);if(t.includes('*'))return 8;if(types[t])return +types[t].slice(1)/8;if(t.startsWith('enum '))return 4;return env.sizes[t];};
 const initialize=(at,t,value)=>{const a=array(t);if(a){const count=+a[2],base=a[1]+a[3],stride=size(base);if(!Number.isInteger(stride))throw Error('Review SHK initializer stride '+base);if(base==='char'&&!Array.isArray(value)){env.copy(at,value,count);return;}if(!Array.isArray(value)||value.length>count)throw Error('Review SHK array initializer '+t);value.forEach((v,i)=>initialize(at+i*stride,base,v));return;}
  if(!t.includes('*')&&(t.startsWith('struct ')||t.startsWith('union '))){const name=t.replace(/^(struct|union) /,''),fields=schema.schema[name]?.fields;if(!Array.isArray(value)||!fields||value.length!==fields.length)throw Error('Review SHK record initializer '+t);value.forEach((v,i)=>{const f=fields[i];if(f.canonical.includes('[')||!f.canonical.includes('*')&&f.canonical.startsWith('struct '))initialize(env.field(at,name,f.name).address,f.canonical,v);else env.field(at,name,f.name).value=v;});return;}env.cell(at,t).value=value;
 };
 env.initialize=initialize;
 for(const row of shk.shkStaticInitializers(env)){const at=env.staticAddress(row.name);env.zero(at,row.size);if(row.values!==null)initialize(at,row.type,row.values);}
 return env;
}
export function callShk(services,name,...args){
 let state=states.get(services.moduleKey);if(!state){state={services};const forwarding=new Proxy(Object.create(null),{get:(_,key)=>Reflect.get(state.services,key,state.services)});state.env=createShkEnvironment(forwarding);states.set(services.moduleKey,state);}
 const fn=shk[name];if(typeof fn!=='function')throw Error('Unknown original SHK function '+name);
 const previous=state.services;state.services=services;
 try{const frame=services.stackSave();try{return withCEnvironment(state.env,fn,...args)??0;}finally{services.stackRestore(frame);}}finally{state.services=previous;}
}
